mapper.sql:
statistic_user_rating AS
(
SELECT product_id as productId,
rating as rating
FROM rating r WHERE user_id = #{userId} AND product_id = #{productId}
)

productFilter AS(
SELECT p.id
FROM product p

    INNER JOIN category_product cp ON p.id = cp.product_id
    WHERE cp.category_id IN

        #{categoryId}

    GROUP BY p.id HAVING COUNT(p.id) = #{listCategoryIds.size()}

)

mapper.update:
UPDATE product
SET is_deleted = true
WHERE id = #{productId}

UPDATE product
SET view = view + 1
WHERE id = #{productId}

UPDATE product SET name = #{productInfo.name}, description = #{productInfo.description},
product_image = #{productInfo.productImage},
price = #{productInfo.price}, brand_id = #{productInfo.brandId} WHERE id = #{productInfo.id}

UPDATE product
SET sold = sold + #{quantity}
WHERE id = #{productId}

UPDATE rating
SET rating = #{ratingInfo.rating}
WHERE user_id = #{userId} AND product_id = #{ratingInfo.productId}
